704	// handleListInstances returns all records of a service, never removing any.
705	func (s *Server) handleListInstances(c *gin.Context) {
706		bag, apiErr := buildParamBag(c)
707		if apiErr != nil {
708			writeError(c, apiErr)
709			return
710		}
711		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
712		if apiErr != nil {
713			writeError(c, apiErr)
714			return
715		}
716		instances, err := s.store.ListInstances(serviceName)
717		if err != nil {
718			writeError(c, errStorageUnavailable())
719			return
720		}
721		wantHealthy, hasFilter := false, false
722		if healthFilter, present := bag.get(healthKeys); present {
723			parsed, ok := parseHealthValue(healthFilter)
724			if !ok {
725				writeError(c, errInvalidParameter("healthy must be a boolean health state"))
726				return
727			}
728			wantHealthy, hasFilter = parsed, true
729		}
730		results := make([]gin.H, 0, len(instances))
731		for _, instance := range instances {
732			if hasFilter && instance.Healthy != wantHealthy {
733				continue
734			}
735			results = append(results, instanceJSON(instance))
736		}
737		sortInstances(results)
738		c.JSON(200, gin.H{"service_name": serviceName, "instances": results})
739	}
